// ---- Storage helpers ----
const Store = {
  get(key, fallback){ try{ return JSON.parse(localStorage.getItem(key)) ?? fallback; }catch(e){ return fallback; } },
  set(key, val){ localStorage.setItem(key, JSON.stringify(val)); }
};

function getCart(){ return Store.get('aurelia_cart', []); }
function setCart(c){ Store.set('aurelia_cart', c); updateNavBadges(); }
function getWishlist(){ return Store.get('aurelia_wishlist', []); }
function setWishlist(w){ Store.set('aurelia_wishlist', w); updateNavBadges(); }

function updateNavBadges(){
  const cartCount = getCart().reduce((s,i)=>s+i.qty,0);
  const wishCount = getWishlist().length;
  document.querySelectorAll('.cart-badge').forEach(b=> b.textContent = cartCount);
  document.querySelectorAll('.wish-badge').forEach(b=> b.textContent = wishCount);
}

function addToCart(id, qty=1, opts={}){
  const cart = getCart();
  const key = id + JSON.stringify(opts);
  const existing = cart.find(i => i.key === key);
  if(existing){ existing.qty += qty; }
  else{
    const p = PRODUCTS.find(p=>p.id===id);
    cart.push({ key, id, name:p.name, img:p.img, price:p.price, oldPrice:p.oldPrice, qty, opts });
  }
  setCart(cart);
  showToast(`Added to cart — ${PRODUCTS.find(p=>p.id===id).name}`, 'cart');
}

function toggleWishlist(id){
  let wish = getWishlist();
  if(wish.includes(id)){ wish = wish.filter(w=>w!==id); showToast('Removed from wishlist','heart'); }
  else{ wish.push(id); showToast('Added to wishlist','heart'); }
  setWishlist(wish);
  document.querySelectorAll(`[data-wish-id="${id}"]`).forEach(el=> el.classList.toggle('active', wish.includes(id)));
}

// ---- Product Card Renderer ----
function productCardHTML(p){
  const inWish = getWishlist().includes(p.id);
  return `
  <div class="product-card reveal">
    <div class="pc-media">
      <a href="product.html?id=${p.id}">
        <img src="${p.img}" alt="${p.name}" loading="lazy">
      </a>
      ${p.badge ? `<span class="pc-badge">${p.badge}</span>` : ''}
      <button class="pc-wish ${inWish?'active':''}" data-wish-id="${p.id}" onclick="toggleWishlist(${p.id})" title="Add to wishlist">&#9825;</button>
      <div class="pc-quick">
        <button class="btn btn-ghost btn-sm btn-block" onclick="openQuickView(${p.id})">Quick View</button>
      </div>
    </div>
    <div class="pc-body">
      <span class="pc-cat">${p.section} · ${p.type||p.cat}</span>
      <a href="product.html?id=${p.id}" class="pc-name">${p.name}</a>
      <span style="font-size:.72rem;color:var(--text-dim);">${p.brand}</span>
      <div class="pc-rating">★★★★★ <span>${p.rating} (${p.reviews})</span></div>
      <div class="pc-price">
        <span class="now">₹${p.price}</span>
        <span class="old">₹${p.oldPrice}</span>
      </div>
      <div class="pc-actions">
        <button class="btn btn-primary" onclick="addToCart(${p.id})">Add to Cart</button>
      </div>
    </div>
  </div>`;
}

function renderGrid(containerId, list){
  const el = document.getElementById(containerId);
  if(!el) return;
  el.innerHTML = list.map(productCardHTML).join('') || `
    <div class="empty-state" style="grid-column:1/-1;">
      <div class="icon-big">🔍</div>
      <h3>No products found</h3>
      <p style="color:var(--text-dim)">Try adjusting your filters or search term.</p>
    </div>`;
  observeReveals();
}

// ---- Quick View Modal ----
function openQuickView(id){
  const p = PRODUCTS.find(p=>p.id===id);
  const overlay = document.getElementById('quickViewOverlay');
  if(!overlay) return;
  document.getElementById('qvContent').innerHTML = `
    <div class="modal-img"><img src="${p.img}" alt="${p.name}"></div>
    <div class="modal-info">
      <span class="pc-cat">${p.section} · ${p.brand}</span>
      <h3>${p.name}</h3>
      <div class="pc-rating">★★★★★ <span>${p.rating} (${p.reviews} reviews)</span></div>
      <div class="pc-price" style="margin:14px 0;"><span class="now">₹${p.price}</span> <span class="old">₹${p.oldPrice}</span></div>
      <p style="color:var(--text-dim);margin-bottom:20px;">${p.desc}</p>
      <div style="display:flex;gap:10px;">
        <button class="btn btn-primary" onclick="addToCart(${p.id});closeQuickView();">Add to Cart</button>
        <a href="product.html?id=${p.id}" class="btn btn-ghost">View Full Details</a>
      </div>
    </div>`;
  overlay.classList.add('show');
}
function closeQuickView(){ document.getElementById('quickViewOverlay')?.classList.remove('show'); }

// ---- Toast Notifications ----
function showToast(msg, icon='check'){
  const map = { check:'✓', cart:'🛍', heart:'♥', error:'!' };
  const container = document.getElementById('toastContainer');
  if(!container) return;
  const t = document.createElement('div');
  t.className = 'toast';
  t.innerHTML = `<span>${map[icon]||'✓'}</span><span>${msg}</span>`;
  container.appendChild(t);
  setTimeout(()=> t.remove(), 3100);
}

// ---- Scroll Reveal Observer ----
function observeReveals(){
  const els = document.querySelectorAll('.reveal:not(.in), .reveal-zoom:not(.in)');
  const io = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
  }, { threshold:0.12 });
  els.forEach(el=> io.observe(el));
}

document.addEventListener('DOMContentLoaded', ()=>{
  updateNavBadges();
  observeReveals();

  const filterToggle = document.getElementById('mobileFilterToggle');
  const filterPanel = document.getElementById('productFilters');
  filterToggle?.addEventListener('click', ()=>{
    const isOpen = filterPanel?.classList.toggle('open') ?? false;
    filterToggle.setAttribute('aria-expanded', String(isOpen));
  });
});
